 $safe=New-ExplorerGraphOperationError -Failure $record -Stage BitLockerSecret
 if ($safe.Message -notlike '*HTTP 403*Graph Authorization_RequestDenied*request-id 88888888-8888-4888-8888-888888888888*' -or $safe.Message -match 'SYNTHETIC_PRIVATE_TOKEN|000011-000011|Authorization:') { throw 'Real SDK HTTP transcript lost diagnostics or exposed private content.' }
